    if (node.type != NodeType::FOOTWAY) {  // Exclude footway roads
        float dx = node.x - x;
        float dy = node.y - y;
        float distance = std::sqrt(dx * dx + dy * dy);

        if (distance < min_distance) {
            min_distance = distance;
            closest_node = const_cast<Node*>(&node);  // Safe cast since we're not modifying
        }
    }
}

